package com.example.starter.slot.domain;

/**
 * 时刻占用依据。
 */
public enum AllocationBasis {

    /** 历史执行率达标（&ge;80%）自动保留的时刻。 */
    RETAINED,

    /** 执行率未达标后进入公共池、经协调分配的时刻。 */
    POOL
}

package com.example.starter.slot.domain;

/**
 * 系列申请的占用状态。
 */
public enum SeriesStatus {

    /** 时刻当前处于占用中（保留或公共池分配）。 */
    HELD,

    /** 系列已被退回，占用时刻已释放回公共池。 */
    RELEASED
}

package com.example.starter.slot.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;

import java.util.List;

/**
 * 系列时刻申请请求。
 *
 * @param requestId 幂等键，同一申请系列在各次重放中必须相同
 * @param season    航季标识，例如 S26
 * @param airline   航司二字码
 * @param flightNo  航班号
 * @param airport   协调机场三字码
 * @param slotTime  申请时刻 HH:mm，必须落在机场时刻池 5 分钟粒度上
 * @param weeks     覆盖周列表（航季内周序号），整周协调
 */
public record SlotApplicationRequest(
        @NotBlank String requestId,
        @NotBlank String season,
        @NotBlank String airline,
        @NotBlank String flightNo,
        @NotBlank String airport,
        @NotBlank String slotTime,
        @NotEmpty List<Integer> weeks) {
}

package com.example.starter.slot.dto;

/**
 * 单个（时刻，周）占用结果。
 *
 * @param airport  机场三字码
 * @param slotTime 时刻 HH:mm
 * @param week     航季内周序号
 * @param basis    占用依据 RETAINED / POOL
 */
public record AllocationView(
        String airport,
        String slotTime,
        Integer week,
        String basis) {
}

package com.example.starter.slot.dto;

import java.util.List;

/**
 * 系列申请裁决结果。
 *
 * @param requestId   幂等键
 * @param decision    裁决依据 RETAINED / POOL
 * @param status      系列当前状态 HELD / RELEASED
 * @param allocations 本系列全部覆盖周的占用明细；退回后为空
 * @param replay      是否为同键同参的幂等重放
 */
public record SlotApplicationResult(
        String requestId,
        String decision,
        String status,
        List<AllocationView> allocations,
        boolean replay) {
}

package com.example.starter.slot.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 系列退回请求。
 *
 * @param requestId 原系列申请幂等键
 */
public record ReleaseRequest(@NotBlank String requestId) {
}

package com.example.starter.slot.dto;

/**
 * 系列退回结果。
 *
 * @param requestId 原系列申请幂等键
 * @param status    退回后系列状态，固定 RELEASED
 * @param replay    是否为同键重复退回（幂等）
 */
public record ReleaseResult(
        String requestId,
        String status,
        boolean replay) {
}

package com.example.starter.slot.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 航季分配表发布请求。
 *
 * @param season 航季标识
 */
public record PublishRequest(@NotBlank String season) {
}

package com.example.starter.slot.dto;

import java.time.Instant;
import java.util.List;

/**
 * 分配表发布结果（即发布时刻的快照视图）。
 *
 * @param season           航季标识
 * @param publishedAt      首次发布时间，重复发布保持不变
 * @param alreadyPublished 是否为重复发布（幂等成功）
 * @param allocations      快照内的全部时刻占用
 */
public record PublishResult(
        String season,
        Instant publishedAt,
        boolean alreadyPublished,
        List<AllocationView> allocations) {
}

