        assertThatThrownBy(() -> service.apply(request("REQ-B", "MU", "2001", "PEK", "08:00", 1, 2, 3)))
                .isInstanceOf(SlotConflictException.class);

        // 系列整体回滚：REQ-B 在 week 1/3 也不得留下占用，且无系列记录
